4	export const dynamic = "force-dynamic";
5	
6	export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
7	  const user = await requireUser().catch(() => null);
8	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
9	  const { id } = await params;
10	
11	  const project = await db.project.findFirst({
12	    where: { id, userId: user.id },
13	    include: {
14	      // Source is what the agent/Code-view work with; the compiled build
15	      // output isn't meant to be shown or edited directly.
16	      files: { where: { published: false, kind: "source" } },
17	      messages: { orderBy: { createdAt: "asc" } },
18	    },
19	  });
20	  if (!project) return Response.json({ error: "Project not found." }, { status: 404 });
21	
22	  return Response.json({ project });
23	}
