7	export default function NewProjectButton() {
8	  const router = useRouter();
9	  const [loading, setLoading] = useState(false);
10	
11	  async function create() {
12	    setLoading(true);
13	    try {
14	      const name = window.prompt("What should we call this site?", "My site");
15	      if (name === null) return;
16	      const { project } = await api<{ project: { id: string } }>("/api/projects", {
17	        method: "POST",
18	        body: JSON.stringify({ name }),
19	      });
20	      router.push(`/projects/${project.id}`);
21	    } finally {
22	      setLoading(false);
23	    }
24	  }
25	
26	  return (
27	    <button
28	      onClick={create}
29	      disabled={loading}
30	      className="rounded-lg bg-black px-3 py-1.5 text-sm font-medium text-white disabled:opacity-50 dark:bg-white dark:text-black"
31	    >
32	      {loading ? "Creating…" : "New site"}
33	    </button>
34	  );
35	}
