1	export class ApiError extends Error {}
2	
3	export async function api<T>(path: string, init?: RequestInit): Promise<T> {
4	  const res = await fetch(path, {
5	    ...init,
6	    headers: { "Content-Type": "application/json", ...init?.headers },
7	  });
8	  const body = await res.json().catch(() => ({}));
9	  if (!res.ok) throw new ApiError(body?.error ?? `Request failed (${res.status})`);
10	  return body as T;
11	}
