import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { track, EVENTS } from "@/lib/events";

export const dynamic = "force-dynamic";

// Same ceiling the create route applies (app/api/projects/route.ts). Kept in
// sync by hand rather than imported: route modules aren't a shared-constants
// home, and that file doesn't export it.
const NAME_MAX = 80;

// Mirrors slugify() in app/api/projects/route.ts. Duplicated rather than
// imported for the same reason as NAME_MAX — importing across route modules
// couples two request entrypoints for one pure function. The random suffix is
// what makes collisions rare; POST below still retries on the off chance.
function slugify(name: string): string {
  const base = name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 40);
  return (base || "site") + "-" + Math.random().toString(36).slice(2, 7);
}

/** Prisma's unique-constraint violation. Structural check so this file needn't import the Prisma error namespace. */
function isUniqueViolation(err: unknown): boolean {
  return typeof err === "object" && err !== null && (err as { code?: string }).code === "P2002";
}

export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const user = await requireUser().catch(() => null);
  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
  const { id } = await params;

  const project = await db.project.findFirst({
    where: { id, userId: user.id },
    include: {
      // Source is what the agent/Code-view work with; the compiled build
      // output isn't meant to be shown or edited directly.
      files: { where: { published: false, kind: "source" } },
      messages: { orderBy: { createdAt: "asc" } },
    },
  });
  if (!project) return Response.json({ error: "Project not found." }, { status: 404 });

  return Response.json({ project });
}

/**
 * Rename. Name only.
 *
 * THE SLUG IS DELIBERATELY NOT REGENERATED HERE.
 *
 * `slug` is the published address (`<slug>.kodely.site`, and the row the public
 * site route resolves by). Renaming is a labelling act — the user is fixing what
 * their dashboard calls the thing — and it must not be able to move a live site
 * out from under its own URL. If rename re-slugged:
 *   - every existing inbound link, share, QR code, and search-engine result for
 *     the published site would 404, silently, with no redirect to fall back on;
 *   - the old slug is globally unique and would be released back into the pool,
 *     so someone else could later claim the exact URL the user just vacated —
 *     a URL takeover triggered by an action that looks purely cosmetic.
 *
 * The same rule applies to unpublished projects, on purpose. Making it
 * conditional ("re-slug only while it's still a draft") would mean the slug
 * shown in the dashboard silently changes for a draft but freezes at publish —
 * a rule nobody can predict from the UI, and one that changes a preview URL the
 * user may already have handed to someone. One rule, always true: a slug is
 * assigned once at creation and never moves.
 *
 * A user who genuinely wants a different address wants a different site, and
 * that is what POST (duplicate) gives them — a new slug, no lost links.
 */
export async function PATCH(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const user = await requireUser().catch(() => null);
  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
  const { id } = await params;

  const body = (await req.json().catch(() => null)) as { name?: unknown } | null;
  if (typeof body?.name !== "string") {
    return Response.json({ error: "A name is required." }, { status: 400 });
  }
  // Trim, cap, then trim again — slicing at 80 can leave a trailing space.
  const name = body.name.trim().slice(0, NAME_MAX).trim();
  if (!name) {
    // The create route falls back to "Untitled site" for a missing name, but a
    // rename is an explicit act: silently renaming someone's site to a
    // placeholder because their input was blank is worse than refusing.
    return Response.json({ error: "A name is required." }, { status: 400 });
  }

  // updateMany, not update: `update` can only filter on unique fields, so it
  // would have to take the id alone and check ownership in a second query.
  // Scoping by { id, userId } in ONE query is what makes a wrong-user id
  // indistinguishable from a nonexistent one.
  const { count } = await db.project.updateMany({
    where: { id, userId: user.id },
    data: { name },
  });
  if (count === 0) return Response.json({ error: "Project not found." }, { status: 404 });

  return Response.json({ project: { id, name } });
}

/**
 * Duplicate — "make a variant of this" without paying for a whole new
 * generation. Charges no credits because nothing is generated: this is a row
 * copy, no model call anywhere on the path.
 *
 * What is copied: the name (suffixed), and every DRAFT file.
 * What is NOT copied:
 *   - publish state. `publishedAt` stays null and no `published: true` rows are
 *     copied, so a duplicate cannot silently go live at a new URL. Going live is
 *     always an explicit act through the publish route.
 *   - messages and builds. The copy is a fresh starting point, not a forked
 *     history; carrying over another project's conversation and its build/cost
 *     records would misattribute both.
 *
 * Draft files are copied for BOTH kinds, not just `kind: "source"`. The editor's
 * preview reads draft `kind: "build"` rows (app/api/preview/[id]) — copying only
 * source would hand the user a duplicate that renders "Nothing built yet" and
 * force a paid rebuild to see it, which is precisely the cost this feature
 * exists to avoid. Both draft trees together are the complete working state.
 */
export async function POST(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const user = await requireUser().catch(() => null);
  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
  const { id } = await params;

  const source = await db.project.findFirst({
    where: { id, userId: user.id },
    include: { files: { where: { published: false } } },
  });
  if (!source) return Response.json({ error: "Project not found." }, { status: 404 });

  // Budget for the suffix before truncating, so the copy marker always survives
  // rather than being the part that gets sliced off an already-long name.
  const SUFFIX = " (copy)";
  const name = source.name.slice(0, NAME_MAX - SUFFIX.length).trim() + SUFFIX;

  // The project row and its files are created in one transaction: a project
  // that exists with an empty file tree is a broken duplicate, and worse than
  // no duplicate at all.
  //
  // Retry wraps the WHOLE transaction. slugify()'s random suffix makes a
  // collision unlikely but not impossible, and a failed statement aborts the
  // surrounding Postgres transaction — so retrying the create in place would
  // run inside a poisoned transaction.
  let copy: { id: string; name: string; slug: string } | null = null;
  for (let attempt = 0; attempt < 5; attempt++) {
    try {
      copy = await db.$transaction(async (tx) => {
        const created = await tx.project.create({
          data: { userId: user.id, name, slug: slugify(name) },
        });
        if (source.files.length > 0) {
          await tx.projectFile.createMany({
            data: source.files.map((f) => ({
              projectId: created.id,
              path: f.path,
              content: f.content,
              published: false,
              kind: f.kind,
            })),
          });
        }
        return created;
      });
      break;
    } catch (err) {
      if (isUniqueViolation(err) && attempt < 4) continue;
      throw err;
    }
  }
  if (!copy) return Response.json({ error: "Couldn't duplicate this site." }, { status: 500 });

  // A duplicate really is a project created, so it belongs in the same funnel.
  // EVENTS is a closed vocabulary by design (see lib/events.ts), so the copy is
  // distinguished by a prop rather than by inventing a name.
  track(EVENTS.projectCreated, {
    userId: user.id,
    props: { projectId: copy.id, source: "duplicate", sourceProjectId: source.id },
  });

  return Response.json({ project: copy });
}

/**
 * Delete. Irreversible — there is no soft-delete column and no undo.
 *
 * Cascade behaviour below was verified against the live Postgres FK catalog
 * (pg_constraint.confdeltype), not just read off schema.prisma:
 *   ProjectFile -> Project  ON DELETE CASCADE
 *   Message     -> Project  ON DELETE CASCADE
 *   Build       -> Project  ON DELETE CASCADE
 *   CreditLedger -> Build   ON DELETE SET NULL
 *
 * Two consequences worth stating explicitly:
 *
 * 1. THIS TAKES A PUBLISHED SITE OFFLINE. The cascade removes the
 *    `published: true` rows the public site route serves, and the Project row
 *    it resolves the slug by — so `<slug>.kodely.site` 404s. Deleting is the
 *    only way to withdraw a published site, and it must actually withdraw it.
 *    (Note: that route sends `Cache-Control: public, max-age=60`, so an already
 *    cached response can survive up to a minute at the edge/browser.)
 *
 * 2. THE CREDIT LEDGER SURVIVES. Builds cascade away, but CreditLedger rows
 *    referencing them are SET NULL, not deleted — the rows remain with
 *    `buildId: null`. getBalance() reads `balanceAfter` off the newest ledger
 *    row (lib/credits.ts), so a delete cannot alter, refund, or erase spend.
 *    That is the correct behaviour for an auditable ledger: deleting the
 *    artifact does not un-charge the work that produced it.
 */
export async function DELETE(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const user = await requireUser().catch(() => null);
  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
  const { id } = await params;

  // Ownership scoped in the same query as the id — see the note on PATCH.
  const { count } = await db.project.deleteMany({ where: { id, userId: user.id } });
  if (count === 0) return Response.json({ error: "Project not found." }, { status: 404 });
  return Response.json({ ok: true });
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { api, ApiError } from "@/lib/api";

// One dashboard row plus its project-management menu (rename / duplicate /
// delete). The row owns this state rather than a sibling menu component,
// because renaming replaces the row's own contents with an input.
//
// Visual rules, kept identical to the rest of the dashboard: monochrome,
// text-sm, black/10 hairlines. The only colour is semantic red on delete.

export type ProjectRowProject = {
  id: string;
  name: string;
  slug: string;
  published: boolean;
};

/** Matches the cap in app/api/projects/[id]/route.ts, so the input can't build a name the server will silently truncate. */
const NAME_MAX = 80;

const FOCUS_RING =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40";

type Mode = "idle" | "renaming" | "deleting";

export default function ProjectRow({ project }: { project: ProjectRowProject }) {
  const router = useRouter();

  const [mode, setMode] = useState<Mode>("idle");
  const [menuOpen, setMenuOpen] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [draftName, setDraftName] = useState(project.name);
  const [confirmText, setConfirmText] = useState("");

  const triggerRef = useRef<HTMLButtonElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const itemRefs = useRef<(HTMLButtonElement | null)[]>([]);

  const closeMenu = useCallback((refocus = false) => {
    setMenuOpen(false);
    if (refocus) triggerRef.current?.focus();
  }, []);

  // Click-outside and Escape while the menu is open.
  useEffect(() => {
    if (!menuOpen) return;
    function onPointerDown(e: MouseEvent) {
      const t = e.target as Node;
      if (menuRef.current?.contains(t) || triggerRef.current?.contains(t)) return;
      setMenuOpen(false);
    }
    function onKeyDown(e: KeyboardEvent) {
      if (e.key === "Escape") {
        e.stopPropagation();
        closeMenu(true);
      }
    }
    document.addEventListener("mousedown", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("mousedown", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [menuOpen, closeMenu]);

  // Move focus into the menu when it opens, so it is usable without a mouse.
  useEffect(() => {
    if (menuOpen) itemRefs.current[0]?.focus();
  }, [menuOpen]);

  function onMenuKeyDown(e: React.KeyboardEvent<HTMLDivElement>) {
    const items = itemRefs.current.filter(Boolean) as HTMLButtonElement[];
    if (items.length === 0) return;
    const current = items.indexOf(document.activeElement as HTMLButtonElement);
    if (e.key === "ArrowDown" || e.key === "ArrowUp") {
      e.preventDefault();
      const delta = e.key === "ArrowDown" ? 1 : -1;
      const next = (current + delta + items.length) % items.length;
      items[next]?.focus();
    } else if (e.key === "Home") {
      e.preventDefault();
      items[0]?.focus();
    } else if (e.key === "End") {
      e.preventDefault();
      items[items.length - 1]?.focus();
    } else if (e.key === "Tab") {
      setMenuOpen(false);
    }
  }

  async function run(fn: () => Promise<void>) {
    setBusy(true);
    setError(null);
    try {
      await fn();
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Something went wrong. Try again.");
    } finally {
      setBusy(false);
    }
  }

  const trimmed = draftName.trim();
  const renameDirty = trimmed.length > 0 && trimmed !== project.name;

  function saveRename() {
    if (!renameDirty) {
      setMode("idle");
      return;
    }
    void run(async () => {
      await api(`/api/projects/${project.id}`, {
        method: "PATCH",
        body: JSON.stringify({ name: trimmed }),
      });
      setMode("idle");
      router.refresh();
    });
  }

  function duplicate() {
    closeMenu();
    void run(async () => {
      await api(`/api/projects/${project.id}`, { method: "POST" });
      router.refresh();
    });
  }

  // Published sites require typing the exact name: deleting one takes a public
  // URL offline, and that is not something to lose to a mis-click. Drafts get
  // the lighter explicit two-step — the whole point of delete is clearing out
  // junk first attempts, and a name-typing gate on every throwaway draft would
  // just train people to type it without reading.
  const requireTypedName = project.published;
  const canDelete = !requireTypedName || confirmText.trim() === project.name;

  function confirmDelete() {
    if (!canDelete) return;
    void run(async () => {
      await api(`/api/projects/${project.id}`, { method: "DELETE" });
      // No local removal — the server list is the source of truth, and refresh
      // re-renders the dashboard without this row.
      router.refresh();
    });
  }

  function closeDelete() {
    setMode("idle");
    setConfirmText("");
    setError(null);
    triggerRef.current?.focus();
  }

  // ---- Renaming: the row becomes an input in place. -------------------------
  if (mode === "renaming") {
    return (
      <div className="px-4 py-2.5">
        <form
          onSubmit={(e) => {
            e.preventDefault();
            saveRename();
          }}
          className="flex items-center gap-2"
        >
          <label htmlFor={`rename-${project.id}`} className="sr-only">
            Site name
          </label>
          <input
            id={`rename-${project.id}`}
            autoFocus
            value={draftName}
            maxLength={NAME_MAX}
            disabled={busy}
            onChange={(e) => setDraftName(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Escape") {
                e.preventDefault();
                setDraftName(project.name);
                setMode("idle");
                setError(null);
                triggerRef.current?.focus();
              }
            }}
            className={`min-w-0 flex-1 rounded-lg border border-black/15 bg-transparent px-2.5 py-1.5 text-sm dark:border-white/15 ${FOCUS_RING}`}
          />
          <button
            type="submit"
            disabled={busy || trimmed.length === 0}
            className={`rounded-lg bg-black px-3 py-1.5 text-sm font-medium text-white disabled:opacity-50 dark:bg-white dark:text-black ${FOCUS_RING}`}
          >
            {busy ? "Saving…" : "Save"}
          </button>
          <button
            type="button"
            disabled={busy}
            onClick={() => {
              setDraftName(project.name);
              setMode("idle");
              setError(null);
              triggerRef.current?.focus();
            }}
            className={`rounded-lg px-2 py-1.5 text-sm text-black/60 hover:text-black disabled:opacity-50 dark:text-white/60 dark:hover:text-white ${FOCUS_RING}`}
          >
            Cancel
          </button>
        </form>
        <p className="mt-1.5 text-xs text-black/45 dark:text-white/45">
          The address stays {project.slug} — renaming never changes a site&rsquo;s URL.
        </p>
        {error && <p className="mt-1 text-xs text-red-600 dark:text-red-400">{error}</p>}
      </div>
    );
  }

  // ---- Normal row + menu, with the delete dialog layered over the page. -----
  return (
    <>
      <div className="flex items-center gap-1 pr-2 hover:bg-black/[0.03] dark:hover:bg-white/[0.03]">
        <Link
          href={`/projects/${project.id}`}
          className={`flex min-w-0 flex-1 items-center justify-between gap-3 px-4 py-3 ${FOCUS_RING}`}
        >
          <span className="truncate text-sm font-medium">{project.name}</span>
          <span className="shrink-0 text-xs text-black/50 dark:text-white/50">
            {project.published ? "Published" : "Draft"} · {project.slug}
          </span>
        </Link>

        <div className="relative shrink-0">
          <button
            ref={triggerRef}
            type="button"
            disabled={busy}
            aria-haspopup="menu"
            aria-expanded={menuOpen}
            aria-label={`Actions for ${project.name}`}
            onClick={() => setMenuOpen((v) => !v)}
            onKeyDown={(e) => {
              if (e.key === "ArrowDown") {
                e.preventDefault();
                setMenuOpen(true);
              }
            }}
            className={`rounded-lg px-2 py-1 text-sm text-black/50 hover:bg-black/5 hover:text-black disabled:opacity-50 dark:text-white/50 dark:hover:bg-white/5 dark:hover:text-white ${FOCUS_RING}`}
          >
            <span aria-hidden="true">···</span>
          </button>

          {menuOpen && (
            <div
              ref={menuRef}
              role="menu"
              aria-label={`Actions for ${project.name}`}
              onKeyDown={onMenuKeyDown}
              className="absolute right-0 z-20 mt-1 w-44 overflow-hidden rounded-xl border border-black/10 bg-white py-1 text-sm shadow-lg dark:border-white/10 dark:bg-neutral-900"
            >
              <button
                ref={(el) => {
                  itemRefs.current[0] = el;
                }}
                role="menuitem"
                type="button"
                onClick={() => {
                  setDraftName(project.name);
                  setMode("renaming");
                  setMenuOpen(false);
                }}
                className={`block w-full px-3 py-1.5 text-left hover:bg-black/5 dark:hover:bg-white/5 ${FOCUS_RING}`}
              >
                Rename
              </button>
              <button
                ref={(el) => {
                  itemRefs.current[1] = el;
                }}
                role="menuitem"
                type="button"
                onClick={duplicate}
                className={`block w-full px-3 py-1.5 text-left hover:bg-black/5 dark:hover:bg-white/5 ${FOCUS_RING}`}
              >
                Duplicate
              </button>
              <div className="my-1 h-px bg-black/10 dark:bg-white/10" />
              <button
                ref={(el) => {
                  itemRefs.current[2] = el;
                }}
                role="menuitem"
                type="button"
                onClick={() => {
                  setConfirmText("");
                  setMode("deleting");
                  setMenuOpen(false);
                }}
                className={`block w-full px-3 py-1.5 text-left text-red-600 hover:bg-red-500/10 dark:text-red-400 ${FOCUS_RING}`}
              >
                Delete…
              </button>
            </div>
          )}
        </div>
      </div>

      {busy && mode === "idle" && (
        <p className="px-4 pb-2 text-xs text-black/45 dark:text-white/45">Working…</p>
      )}
      {error && mode === "idle" && (
        <p className="px-4 pb-2 text-xs text-red-600 dark:text-red-400">{error}</p>
      )}

      {mode === "deleting" && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4"
          onMouseDown={(e) => {
            if (e.target === e.currentTarget) closeDelete();
          }}
        >
          <div
            role="dialog"
            aria-modal="true"
            aria-labelledby={`delete-title-${project.id}`}
            onKeyDown={(e) => {
              if (e.key === "Escape") {
                e.preventDefault();
                closeDelete();
              }
            }}
            className="w-full max-w-sm rounded-xl border border-black/10 bg-white p-5 text-sm shadow-xl dark:border-white/10 dark:bg-neutral-900"
          >
            <h2 id={`delete-title-${project.id}`} className="text-sm font-medium">
              Delete {project.name}?
            </h2>

            <p className="mt-2 text-sm text-black/60 dark:text-white/60">
              This deletes the site, its files, its chat history and its build history.{" "}
              <strong className="font-medium text-black dark:text-white">
                This cannot be undone — there is no way to get it back.
              </strong>
            </p>

            {project.published && (
              <p className="mt-2 text-sm text-red-600 dark:text-red-400">
                {project.slug}.kodely.site is live. Deleting takes it offline immediately and
                the address cannot be reclaimed.
              </p>
            )}

            <p className="mt-2 text-xs text-black/45 dark:text-white/45">
              Your credit history and balance are unaffected.
            </p>

            {requireTypedName ? (
              <div className="mt-4">
                <label htmlFor={`confirm-${project.id}`} className="block text-xs text-black/60 dark:text-white/60">
                  Type <span className="font-medium text-black dark:text-white">{project.name}</span> to
                  confirm
                </label>
                <input
                  id={`confirm-${project.id}`}
                  autoFocus
                  value={confirmText}
                  disabled={busy}
                  autoComplete="off"
                  onChange={(e) => setConfirmText(e.target.value)}
                  className={`mt-1.5 w-full rounded-lg border border-black/15 bg-transparent px-2.5 py-1.5 text-sm dark:border-white/15 ${FOCUS_RING}`}
                />
              </div>
            ) : (
              <p className="mt-4 text-xs text-black/60 dark:text-white/60">
                Press Delete to confirm.
              </p>
            )}

            {error && <p className="mt-3 text-xs text-red-600 dark:text-red-400">{error}</p>}

            <div className="mt-5 flex justify-end gap-2">
              <button
                type="button"
                disabled={busy}
                onClick={closeDelete}
                className={`rounded-lg border border-black/15 px-3 py-1.5 text-sm disabled:opacity-50 dark:border-white/15 ${FOCUS_RING}`}
              >
                Cancel
              </button>
              <button
                type="button"
                autoFocus={!requireTypedName}
                disabled={busy || !canDelete}
                onClick={confirmDelete}
                className={`rounded-lg bg-red-600 px-3 py-1.5 text-sm font-medium text-white disabled:opacity-40 dark:bg-red-500 ${FOCUS_RING}`}
              >
                {busy ? "Deleting…" : "Delete"}
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

