import { PrismaClient } from 'file:///C:/Users/edmem/kodely-prod/node_modules/@prisma/client/default.js';
import { createHash, randomBytes } from 'node:crypto';

const BASE = 'http://localhost:3003';
const db = new PrismaClient({ datasources: { db: { url: "postgresql://postgres:mafiakid3@localhost:5432/kodely_personal" } } });

let pass = 0, fail = 0;
const ok = (c, msg) => { if (c) { pass++; console.log('  PASS ' + msg); } else { fail++; console.log('  FAIL ' + msg); } };

const sha = (t) => createHash('sha256').update(t).digest('hex');
async function mkUser(tag) {
  const u = await db.user.create({ data: { email: `e2e-${tag}-${Date.now()}@kodely-test.invalid`, name: `e2e ${tag}` } });
  const token = randomBytes(32).toString('base64url');
  await db.session.create({ data: { userId: u.id, tokenHash: sha(token), expiresAt: new Date(Date.now() + 3600_000) } });
  return { ...u, token };
}
const call = (user, path, init = {}) => fetch(BASE + path, {
  ...init, redirect: 'manual',
  headers: { 'Content-Type': 'application/json', ...(user ? { Cookie: `kodely_session=${user.token}` } : {}), ...init.headers },
});

const created = { users: [], projects: [] };

try {
  const A = await mkUser('a'); created.users.push(A.id);
  const B = await mkUser('b'); created.users.push(B.id);

  console.log('\n[0] same-DB / auth sanity');
  const me = await call(A, '/api/auth/me').then(r => r.json());
  ok(me?.user?.id === A.id, 'dev server on :3003 shares this database and honours the session');

  // --- fixture: a PUBLISHED project with the full object graph -------------
  const P = await db.project.create({ data: { userId: A.id, name: 'E2E Original', slug: `e2e-orig-${Date.now().toString(36)}`, publishedAt: new Date() } });
  created.projects.push(P.id);
  await db.projectFile.createMany({ data: [
    { projectId: P.id, path: 'src/App.tsx', content: 'draft source', published: false, kind: 'source' },
    { projectId: P.id, path: 'index.html', content: '<html><head></head><body>draft build</body></html>', published: false, kind: 'build' },
    { projectId: P.id, path: 'index.html', content: '<html><head></head><body>LIVE</body></html>', published: true, kind: 'build' },
  ]});
  await db.message.create({ data: { projectId: P.id, role: 'user', content: 'make it blue' } });
  const build = await db.build.create({ data: { projectId: P.id, status: 'SUCCEEDED', model: 'test', prompt: 'p', creditsCharged: 12 } });
  const ledger = await db.creditLedger.create({ data: { userId: A.id, delta: -12, reason: 'build', buildId: build.id, balanceAfter: 738 } });

  console.log('\n[1] ownership scoping — user B must not touch user A\'s project');
  for (const [m, init] of [['PATCH', { method: 'PATCH', body: JSON.stringify({ name: 'hacked' }) }], ['POST', { method: 'POST' }], ['DELETE', { method: 'DELETE' }]]) {
    const r = await call(B, `/api/projects/${P.id}`, init);
    const body = await r.json();
    ok(r.status === 404 && body.error === 'Project not found.',
      `${m} as wrong user -> 404 "Project not found." (got ${r.status} ${JSON.stringify(body.error)})`);
  }
  const afterB = await db.project.findUnique({ where: { id: P.id } });
  ok(afterB && afterB.name === 'E2E Original', 'project untouched after B\'s attempts');
  ok((await db.project.count({ where: { userId: B.id } })) === 0, 'no project was duplicated into B\'s account');

  console.log('\n[2] unauthenticated');
  for (const [m, init] of [['PATCH', { method: 'PATCH', body: JSON.stringify({ name: 'x' }) }], ['POST', { method: 'POST' }], ['DELETE', { method: 'DELETE' }]]) {
    const r = await call(null, `/api/projects/${P.id}`, init);
    ok(r.status === 401, `${m} with no session -> 401 (got ${r.status})`);
  }

  console.log('\n[3] rename');
  const slugBefore = afterB.slug, pubBefore = afterB.publishedAt.toISOString();
  let r = await call(A, `/api/projects/${P.id}`, { method: 'PATCH', body: JSON.stringify({ name: '   Renamed E2E   ' }) });
  ok(r.status === 200, `rename -> 200 (got ${r.status})`);
  let row = await db.project.findUnique({ where: { id: P.id } });
  ok(row.name === 'Renamed E2E', `name trimmed -> ${JSON.stringify(row.name)}`);
  ok(row.slug === slugBefore, `SLUG UNCHANGED after rename (${row.slug})`);
  ok(row.publishedAt.toISOString() === pubBefore, 'publishedAt untouched by rename');

  r = await call(A, `/api/projects/${P.id}`, { method: 'PATCH', body: JSON.stringify({ name: 'Z'.repeat(200) }) });
  row = await db.project.findUnique({ where: { id: P.id } });
  ok(r.status === 200 && row.name.length === 80, `200-char name capped at 80 (got ${row.name.length})`);

  for (const [label, payload] of [['empty', { name: '' }], ['whitespace only', { name: '   ' }], ['missing', {}], ['non-string', { name: 42 }]]) {
    const rr = await call(A, `/api/projects/${P.id}`, { method: 'PATCH', body: JSON.stringify(payload) });
    ok(rr.status === 400, `rename with ${label} name -> 400 (got ${rr.status})`);
  }
  const rr = await call(A, `/api/projects/${P.id}`, { method: 'PATCH', body: 'not json' });
  ok(rr.status === 400, `rename with malformed JSON -> 400 (got ${rr.status})`);
  await db.project.update({ where: { id: P.id }, data: { name: 'Renamed E2E' } });

  console.log('\n[4] published site is live before delete');
  const live = await fetch(`${BASE}/api/site/${slugBefore}`);
  ok(live.status === 200 && (await live.text()).includes('LIVE'), `GET /api/site/${slugBefore} -> 200 serving published build`);

  console.log('\n[5] duplicate');
  const balBefore = (await db.creditLedger.findFirst({ where: { userId: A.id }, orderBy: { createdAt: 'desc' } })).balanceAfter;
  const ledgerCountBefore = await db.creditLedger.count({ where: { userId: A.id } });
  r = await call(A, `/api/projects/${P.id}`, { method: 'POST' });
  const dup = (await r.json()).project;
  ok(r.status === 200 && !!dup?.id, `duplicate -> 200 (got ${r.status})`);
  created.projects.push(dup.id);
  const copy = await db.project.findUnique({ where: { id: dup.id }, include: { files: true, messages: true, builds: true } });
  ok(copy.name === 'Renamed E2E (copy)', `copy name -> ${JSON.stringify(copy.name)}`);
  ok(copy.slug !== slugBefore && copy.slug.length > 0, `copy has a NEW slug (${copy.slug} != ${slugBefore})`);
  ok(copy.userId === A.id, 'copy owned by A');
  ok(copy.publishedAt === null, 'copy is NOT published (publishedAt null)');
  ok(copy.files.filter(f => f.published).length === 0, 'copy has NO published files -> nothing went live at the new URL');
  ok(copy.files.filter(f => !f.published && f.kind === 'source').length === 1, 'draft source file copied');
  ok(copy.files.filter(f => !f.published && f.kind === 'build').length === 1, 'draft build file copied (editor preview works without a paid rebuild)');
  ok(copy.messages.length === 0, 'copy has NO message history');
  ok(copy.builds.length === 0, 'copy has NO build history');
  const siteOfCopy = await fetch(`${BASE}/api/site/${copy.slug}`);
  ok(siteOfCopy.status === 404, `copy's slug is NOT publicly served -> 404 (got ${siteOfCopy.status})`);
  ok((await db.creditLedger.count({ where: { userId: A.id } })) === ledgerCountBefore, 'duplicate wrote NO credit ledger row (charged nothing)');

  // long-name suffix budgeting
  await db.project.update({ where: { id: P.id }, data: { name: 'L'.repeat(80) } });
  const r2 = await call(A, `/api/projects/${P.id}`, { method: 'POST' });
  const dup2 = (await r2.json()).project; created.projects.push(dup2.id);
  ok(dup2.name.length <= 80 && dup2.name.endsWith(' (copy)'), `80-char name duplicates to <=80 chars keeping the marker (len ${dup2.name.length})`);
  await db.project.update({ where: { id: P.id }, data: { name: 'Renamed E2E' } });

  console.log('\n[6] delete + cascade (the real question)');
  r = await call(A, `/api/projects/${P.id}`, { method: 'DELETE' });
  ok(r.status === 200, `delete -> 200 (got ${r.status})`);
  ok((await db.project.findUnique({ where: { id: P.id } })) === null, 'project row gone');
  ok((await db.projectFile.count({ where: { projectId: P.id } })) === 0, 'CASCADE: all ProjectFile rows gone (draft AND published)');
  ok((await db.message.count({ where: { projectId: P.id } })) === 0, 'CASCADE: Message rows gone');
  ok((await db.build.count({ where: { projectId: P.id } })) === 0, 'CASCADE: Build rows gone');
  const led = await db.creditLedger.findUnique({ where: { id: ledger.id } });
  ok(led !== null, 'SET NULL: CreditLedger row SURVIVES the cascade');
  ok(led && led.buildId === null, 'SET NULL: its buildId is now null');
  ok(led && led.balanceAfter === 738, 'ledger balanceAfter untouched');
  const balAfter = (await db.creditLedger.findFirst({ where: { userId: A.id }, orderBy: { createdAt: 'desc' } })).balanceAfter;
  ok(balAfter === balBefore, `balance unchanged by delete (${balBefore} -> ${balAfter})`);
  const gone = await fetch(`${BASE}/api/site/${slugBefore}`);
  ok(gone.status === 404, `PUBLISHED SITE IS OFFLINE: GET /api/site/${slugBefore} -> 404 (got ${gone.status})`);
  const r404 = await call(A, `/api/projects/${P.id}`, { method: 'DELETE' });
  ok(r404.status === 404, `second delete -> 404 (got ${r404.status})`);
  ok((await call(A, `/api/projects/${P.id}`, { method: 'PATCH', body: JSON.stringify({ name: 'x' }) })).status === 404, 'rename of deleted project -> 404');

} catch (e) {
  fail++; console.error('\nERROR', e);
} finally {
  console.log('\n[cleanup] removing only rows this script created');
  for (const id of created.projects) await db.project.deleteMany({ where: { id } });
  for (const id of created.users) await db.user.deleteMany({ where: { id } });
  console.log(`\n===== ${pass} passed, ${fail} failed =====`);
  await db.$disconnect();
  process.exit(fail ? 1 : 0);
}

